        raise ValueError("Archive is empty")

    selected_idx = random.randint(0, len(archive) - 1)
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    n = len(new_solution)
    if n < 4:
        if n > 1:
            i, j = random.sample(range(n), 2)
            new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
    else:
        obj1, obj2, obj3 = archive[selected_idx][1]
        if random.random() < 0.6:
            i, j = sorted(random.sample(range(n), 2))
            new_solution[i:j+1] = new_solution[i:j+1][::-1]
        else:
            weights = [obj1, obj2, obj3]
            chosen_obj = random.choices([0, 1, 2], weights=weights)[0]
            if chosen_obj == 0:
                i, j = random.sample(range(n), 2)
                if distance_matrix_1[new_solution[i-1], new_solution[j]] + distance_matrix_1[new_solution[j], new_solution[(i+1)%n]] < distance_matrix_1[new_solution[i-1], new_solution[i]] + distance_matrix_1[new_solution[j], new_solution[(j+1)%n]]:
                    new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
            elif chosen_obj == 1:
                i, j = random.sample(range(n), 2)
                if distance_matrix_2[new_solution[i-1], new_solution[j]] + distance_matrix_2[new_solution[j], new_solution[(i+1)%n]] < distance_matrix_2[new_solution[i-1], new_solution[i]] + distance_matrix_2[new_solution[j], new_solution[(j+1)%n]]:
                    new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
            else:
                i, j = random.sample(range(n), 2)
                if distance_matrix_3[new_solution[i-1], new_solution[j]] + distance_matrix_3[new_solution[j], new_solution[(i+1)%n]] < distance_matrix_3[new_solution[i-1], new_solution[i]] + distance_matrix_3[new_solution[j], new_solution[(j+1)%n]]:
                    new_solution[i], new_solution[j] = new_solution[j], new_solution[i]

    if len(set(new_solution)) != n or not np.array_equal(np.sort(new_solution), np.arange(n)):
        new_solution = base_solution.copy()

    return new_solution

