    # Select a solution with high Pareto dominance potential
    selected_idx = random.randint(0, len(archive) - 1)
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    n = len(new_solution)
    if n < 5:
        # Simple 2.5-opt for very small instances
        if n > 2:
            i, j, k = sorted(random.sample(range(n), 3))
            segment1 = new_solution[i:j+1]
            segment2 = new_solution[j+1:k+1]
            if random.random() < 0.5:
                new_solution = np.concatenate([new_solution[:i], segment2, segment1, new_solution[k+1:]])
            else:
                new_solution = np.concatenate([new_solution[:i], segment2[::-1], segment1[::-1], new_solution[k+1:]])
    else:
        # Adaptive segment swapping
        obj1, obj2, obj3 = archive[selected_idx][1]
        if random.random() < 0.6:
            # Swap segments to potentially improve the dominant objective
            i, j, k = sorted(random.sample(range(n), 3))
            segment1 = new_solution[i:j+1]
            segment2 = new_solution[j+1:k+1]
            if obj1 > obj2 and obj1 > obj3:
                # Focus on improving first objective
                if random.random() < 0.7:
                    new_solution = np.concatenate([new_solution[:i], segment2, segment1, new_solution[k+1:]])
                else:
                    new_solution = np.concatenate([new_solution[:i], segment2[::-1], segment1, new_solution[k+1:]])
            elif obj2 > obj1 and obj2 > obj3:
                # Focus on improving second objective
                if random.random() < 0.7:
                    new_solution = np.concatenate([new_solution[:i], segment2, segment1, new_solution[k+1:]])
                else:
                    new_solution = np.concatenate([new_solution[:i], segment2, segment1[::-1], new_solution[k+1:]])
            else:
                # Focus on improving third objective
                if random.random() < 0.7:
                    new_solution = np.concatenate([new_solution[:i], segment2, segment1, new_solution[k+1:]])
                else:
                    new_solution = np.concatenate([new_solution[:i], segment2[::-1], segment1[::-1], new_solution[k+1:]])
        else:
            # Multi-objective-aware 2.5-opt operator
            i, j, k, l = sorted(random.sample(range(n), 4))
            segment1 = new_solution[i:j+1]
            segment2 = new_solution[j+1:k+1]
            segment3 = new_solution[k+1:l+1]
            if random.random() < 0.5:
                new_solution = np.concatenate([new_solution[:i], segment2, segment1, segment3, new_solution[l+1:]])
            else:
                new_solution = np.concatenate([new_solution[:i], segment2[::-1], segment1[::-1], segment3, new_solution[l+1:]])

    # Ensure feasibility
